.preview-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-card);
  padding: 20px;
  width: 320px;
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.preview-card__image-wrap {
  border-radius: 10px;
  overflow: hidden;
  aspect-ratio: 4 / 3;
  background: #252836;
  display: flex;
  align-items: center;
  justify-content: center;
}

.preview-card__image-wrap img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.preview-card__meta {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.preview-card__title {
  font-size: 0.95rem;
  font-weight: 600;
  color: var(--text-primary);
}

.preview-card__subtitle {
  font-size: 0.8rem;
  color: var(--text-secondary);
}

.preview-card__actions {
  display: flex;
  gap: 10px;
}

/* ── Buttons ──────────────────────────────────────────────── */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 8px 16px;
  border-radius: var(--radius-btn);
  font-size: 0.85rem;
  font-weight: 500;
  cursor: pointer;
  border: 1px solid transparent;
  transition: background var(--transition), border-color var(--transition), color var(--transition);
  line-height: 1;
  text-decoration: none;
  white-space: nowrap;
}

.btn--ghost {
  background: transparent;
  border-color: var(--border);
  color: var(--text-secondary);
}
.btn--ghost:hover { background: var(--accent-ghost-hov); color: var(--text-primary); }

.btn--danger {
  background: var(--accent-red);
  border-color: var(--accent-red);
  color: #fff;
}
.btn--danger:hover { background: var(--accent-red-hov); border-color: var(--accent-red-hov); }

.btn--outline-danger {
  background: transparent;
  border-color: var(--accent-red);
  color: var(--accent-red);
}
.btn--outline-danger:hover { background: rgba(229, 83, 75, 0.12); }

.btn:focus-visible {
  outline: 2px solid #6c8af5;
  outline-offset: 2px;
}

/* delete trigger — grows to fill available space on left */
.btn.trigger {
  flex: 1;
}

