.dialog__header {
  display: flex;
  align-items: flex-start;
  gap: 14px;
}

.dialog__icon {
  flex-shrink: 0;
  width: 42px;
  height: 42px;
  border-radius: 50%;
  background: rgba(229, 83, 75, 0.15);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--accent-red);
}

.dialog__icon svg { width: 20px; height: 20px; }

.dialog__title-group { display: flex; flex-direction: column; gap: 4px; }

.dialog__title {
  font-size: 1.05rem;
  font-weight: 700;
  color: var(--text-primary);
}

.dialog__description {
  font-size: 0.875rem;
  color: var(--text-secondary);
  line-height: 1.55;
}

/* ── Image thumbnail inside dialog ───────────────────────── */
.dialog__preview {
  display: flex;
  align-items: center;
  gap: 12px;
  background: rgba(255,255,255,0.04);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 10px 12px;
}

.dialog__preview-thumb {
  width: 48px;
  height: 48px;
  border-radius: 6px;
  object-fit: cover;
  flex-shrink: 0;
  background: #252836;
}

.dialog__preview-info { display: flex; flex-direction: column; gap: 2px; }

.dialog__preview-name {
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--text-primary);
}

.dialog__preview-size {
  font-size: 0.78rem;
  color: var(--text-secondary);
}

/* ── Dialog footer ────────────────────────────────────────── */
.dialog__footer {
  display: flex;
  gap: 10px;
  justify-content: flex-end;
}

/* ── Visually hidden (accessible) ────────────────────────── */
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0,0,0,0);
  white-space: nowrap;
  border-width: 0;
}
